"""Tool registry and dispatch for code generated by protoc-gen-mcp."""

from __future__ import annotations

import json
import weakref
from dataclasses import dataclass
from typing import Any

import jsonschema
import mcp.server.lowlevel
import mcp.server.session
import mcp.shared.exceptions
import mcp.types
from google.protobuf import json_format

from ._util import maybe_await, message_to_json

ToolRequestContext = mcp.server.session.ServerSession


@dataclass(frozen=True)
class RegisteredTool:
    """One generated tool: its MCP metadata, schemas, protobuf types and handler."""

    name: str
    title: str
    description: str
    input_schema_json: str
    output_schema_json: str
    request_type: type[Any]
    response_type: type[Any]
    from_pb: Any
    to_pb: Any
    handler: Any
    annotations: dict[str, Any] | None
    icons: list[dict[str, Any]] | None
    execution: dict[str, Any] | None = None
    meta: dict[str, Any] | None = None
    required_scopes: tuple[str, ...] = ()


class ToolRegistry:
    """Tools registered on one low-level server, shared by every generated module."""

    def __init__(self, server: mcp.server.lowlevel.Server) -> None:
        self.server = server
        self.tools: dict[str, RegisteredTool] = {}
        self.previous_list_tools: Any | None = None
        self.previous_call_tool: Any | None = None

    def add_tool(self, tool: RegisteredTool) -> None:
        if tool.name in self.tools:
            raise ValueError(f"duplicate tool registration: {tool.name}")
        self.tools[tool.name] = tool

    def list_tools(self) -> list[mcp.types.Tool]:
        return [build_tool(tool) for tool in self.tools.values()]

    async def call_tool(
        self,
        name: str,
        arguments: dict[str, Any] | None,
        context: ToolRequestContext | None = None,
        granted_scopes: list[str] | None = None,
    ) -> mcp.types.CallToolResult:
        return await dispatch_call(self, name, arguments or {}, context, granted_scopes)


_REGISTRIES: weakref.WeakKeyDictionary[mcp.server.lowlevel.Server, ToolRegistry] = weakref.WeakKeyDictionary()


def normalize_tool_segment(segment: str | None) -> str:
    if segment is None:
        return ""
    parts = [part for part in segment.strip().replace(".", "_").split("_") if part]
    return "_".join(parts)


def normalize_namespace(namespace: str | None, default: str) -> str:
    if namespace is None:
        namespace = default
    return normalize_tool_segment(namespace)


def tool_name(namespace: str, method_name: str) -> str:
    namespace = normalize_tool_segment(namespace)
    method_name = normalize_tool_segment(method_name)
    if namespace == "":
        return method_name
    if method_name == "":
        return namespace
    return f"{namespace}_{method_name}"


def install_tool_registry(server: mcp.server.lowlevel.Server) -> ToolRegistry:
    """Returns the server's tool registry, installing tools/list and tools/call once.

    Handlers the application registered before keep working: their tools are
    listed first and unknown tool names are forwarded to them.
    """
    registry = _REGISTRIES.get(server)
    if registry is not None:
        return registry
    registry = ToolRegistry(server)
    _REGISTRIES[server] = registry
    registry.previous_list_tools = server.request_handlers.get(mcp.types.ListToolsRequest)
    registry.previous_call_tool = server.request_handlers.get(mcp.types.CallToolRequest)

    async def _list_tools(request: Any) -> mcp.types.ServerResult:
        list_request = request if isinstance(request, mcp.types.ListToolsRequest) else mcp.types.ListToolsRequest()
        previous_tools: list[mcp.types.Tool] = []
        meta: dict[str, Any] | None = None
        if registry.previous_list_tools is not None:
            previous_result = await registry.previous_list_tools(list_request)
            if not isinstance(previous_result.root, mcp.types.ListToolsResult):
                return previous_result
            if getattr(list_request.params, "cursor", None) is not None or previous_result.root.nextCursor is not None:
                raise ValueError("cannot compose protoc-gen-mcp tools with paginated tools/list handlers")
            meta = getattr(previous_result.root, "meta", None)
            previous_tools = list(previous_result.root.tools)
        tools = _merge_tools(previous_tools, registry.list_tools())
        server._tool_cache.clear()
        for tool in tools:
            server._tool_cache[tool.name] = tool
        return mcp.types.ServerResult(mcp.types.ListToolsResult(tools=tools, _meta=meta))

    async def _call_tool(request: mcp.types.CallToolRequest) -> mcp.types.ServerResult:
        if request.params.name not in registry.tools:
            if registry.previous_call_tool is not None:
                return await registry.previous_call_tool(request)
            raise invalid_params_error(request.params.name, "unknown tool")
        if registry.previous_call_tool is not None:
            await server.request_handlers[mcp.types.ListToolsRequest](mcp.types.ListToolsRequest())
        result = await registry.call_tool(
            request.params.name,
            request.params.arguments or {},
            server.request_context.session,
            granted_scopes(server),
        )
        return mcp.types.ServerResult(result)

    server.request_handlers[mcp.types.ListToolsRequest] = _list_tools
    server.request_handlers[mcp.types.CallToolRequest] = _call_tool
    return registry


def _merge_tools(previous: list[mcp.types.Tool], current: list[mcp.types.Tool]) -> list[mcp.types.Tool]:
    merged: list[mcp.types.Tool] = []
    names: set[str] = set()
    for tool in [*previous, *current]:
        if tool.name in names:
            raise ValueError(f"duplicate tool registration: {tool.name}")
        names.add(tool.name)
        merged.append(tool)
    return merged


def tool_error_result(message: str) -> mcp.types.CallToolResult:
    return mcp.types.CallToolResult(
        content=[mcp.types.TextContent(type="text", text=message)],
        isError=True,
    )


def invalid_params_error(tool: str, error: Any) -> mcp.shared.exceptions.McpError:
    return mcp.shared.exceptions.McpError(
        mcp.types.ErrorData(
            code=mcp.types.INVALID_PARAMS,
            message=f"invalid arguments for tool {tool!r}: {error}",
        )
    )


def build_tool(tool: RegisteredTool) -> mcp.types.Tool:
    return mcp.types.Tool(
        name=tool.name,
        title=tool.title,
        description=tool.description,
        inputSchema=json.loads(tool.input_schema_json),
        outputSchema=json.loads(tool.output_schema_json),
        annotations=None if tool.annotations is None else mcp.types.ToolAnnotations(**tool.annotations),
        icons=tool.icons,
        execution=None if tool.execution is None else mcp.types.ToolExecution(**tool.execution),
        _meta=tool.meta,
    )


def granted_scopes(server: mcp.server.lowlevel.Server) -> list[str] | None:
    """Scopes of the bearer token behind the current request, or None without one."""
    try:
        request = server.request_context.request
    except LookupError:
        return None
    user = None if request is None else request.scope.get("user")
    access_token = getattr(user, "access_token", None)
    return None if access_token is None else list(access_token.scopes)


async def dispatch_call(
    registry: ToolRegistry,
    name: str,
    arguments: dict[str, Any],
    context: ToolRequestContext | None,
    granted: list[str] | None = None,
) -> mcp.types.CallToolResult:
    """Checks scopes, validates, decodes and runs one tool call, then validates its output."""
    tool = registry.tools.get(name)
    if tool is None:
        raise invalid_params_error(name, "unknown tool")
    if tool.required_scopes:
        # Defence in depth behind the HTTP scope check; stdio has no token.
        if granted is None:
            return tool_error_result("permission denied: an authenticated token is required")
        for scope in tool.required_scopes:
            if scope not in granted:
                return tool_error_result(f'permission denied: missing required scope "{scope}"')
    try:
        jsonschema.validate(arguments, json.loads(tool.input_schema_json))
    except jsonschema.ValidationError as error:
        raise invalid_params_error(name, error) from error
    try:
        request_pb = tool.request_type()
        json_format.ParseDict(arguments, request_pb)
        request = tool.from_pb(request_pb)
    except Exception as error:
        raise invalid_params_error(name, error) from error
    try:
        response = await maybe_await(tool.handler(context, request))
    except Exception as error:
        return tool_error_result(str(error))
    try:
        response_pb = tool.response_type() if response is None else tool.to_pb(response)
        payload = json.loads(message_to_json(response_pb))
    except Exception as error:
        raise RuntimeError(f"mcpruntime: marshal output for tool {name!r}: {error}") from error
    text = json.dumps(payload, separators=(",", ":"), ensure_ascii=False)
    try:
        jsonschema.validate(payload, json.loads(tool.output_schema_json))
    except jsonschema.ValidationError as error:
        raise RuntimeError(f"mcpruntime: validate output for tool {name!r}: {error}") from error
    return mcp.types.CallToolResult(
        content=[mcp.types.TextContent(type="text", text=text)],
        structuredContent=payload,
    )
